window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c07dbaf7cdeec8fc"]={"versions": [{"id": "FIG-c07dbaf7cdeec8fc", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Interaktions- und Datenflussdiagramm (Architekturübersicht mit schematischer Speicherbelegung) im Kontext der OBD-II-/WWH-OBD-Diensteverarbeitung der AUTOSAR Classic Platform (DCM- und DEM-Interaktion).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>External Tester</strong>: Diagnoseprüfgerät außerhalb des Steuergeräts.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Abwicklung von Diagnoseanfragen und -antworten.\n</li><li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Speicherung und Verwaltung diagnostischer Ereignisse und Fehlerspeicherdaten.\n</li><li><strong>Schnittstelle / Funktionsaufruf</strong>: <code>Dem_GetDTCOfFreezeFrameRecord</code> (Funktionsaufruf von DCM an DEM zur Abfrage des zu einem Freeze-Frame-Datensatz gehörenden DTCs; Rückgabewert ist der DTC).\n</li><li><strong>Event memory</strong>: Ereignisspeicher des DEM, strukturiert nach DTC-Einträgen (z. B. DTC1, DTC2, free) und zugeordneten Freeze-Frame-Speicherplätzen (z. B. 1. Set, 2. Set, freie Plätze).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <strong>External Tester</strong> sendet eine Diagnoseanfrage für OBD-Freeze-Frame-Daten an das <strong>DCM</strong>: <code>Request: $02 $02 $00</code> (Beispiel für FreezeFrame-Record 0x00 bei OBD-Service $02).\n</li><li>Das <strong>DCM</strong> ruft beim <strong>DEM</strong> die Funktion <code>Dem_GetDTCOfFreezeFrameRecord</code> auf.\n</li><li>Das <strong>DEM</strong> ermittelt aus dem Ereignisspeicher (<code>Event memory</code>) den zugeordneten DTC anhand der gespeicherten Freeze-Frame-Datensätze.\n</li><li>Das <strong>DEM</strong> liefert den DTC als Rückgabewert (<code>Return value(s)</code>) an das <strong>DCM</strong> zurück.\n</li><li>Das <strong>DCM</strong> antwortet dem <strong>External Tester</strong> mit der positiven Antwortnachricht: <code>Response: $42 $02 $00 [ DTC high byte + DTC low byte ]</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht den Ablauf für OBD Service $02 (Mode 02 – Request Powertrain Freeze Frame Data) zur Ermittlung des verursachenden Fehlercodes (DTC) für einen spezifischen Freeze-Frame-Datensatz.\n</li><li>Implementierer müssen sicherstellen, dass das DCM den Freeze-Frame-Datensatzindex korrekt an das DEM über <code>Dem_GetDTCOfFreezeFrameRecord</code> übergibt und die zurückgelieferten High- und Low-Bytes des 2-Byte-OBD-DTCs in das Payload-Format der Service-$02-Antwort einbettet.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-11676271afaad090", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Interaktions- und Datenflussdiagramm (Architekturübersicht mit schematischer Speicherbelegung) im Kontext der OBD-II-/WWH-OBD-Diensteverarbeitung der AUTOSAR Classic Platform (DCM- und DEM-Interaktion).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>External Tester</strong>: Diagnoseprüfgerät außerhalb des Steuergeräts.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Abwicklung von Diagnoseanfragen und -antworten.\n</li><li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Speicherung und Verwaltung diagnostischer Ereignisse und Fehlerspeicherdaten.\n</li><li><strong>Schnittstelle / Funktionsaufruf</strong>: <code>Dem_GetDTCOfFreezeFrameRecord</code> (Funktionsaufruf von DCM an DEM zur Abfrage des zu einem Freeze-Frame-Datensatz gehörenden DTCs; Rückgabewert ist der DTC).\n</li><li><strong>Event memory</strong>: Ereignisspeicher des DEM, strukturiert nach DTC-Einträgen (z. B. DTC1, DTC2, free) und zugeordneten Freeze-Frame-Speicherplätzen (z. B. 1. Set, 2. Set, freie Plätze).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <strong>External Tester</strong> sendet eine Diagnoseanfrage für OBD-Freeze-Frame-Daten an das <strong>DCM</strong>: <code>Request: $02 $02 $00</code> (Beispiel für FreezeFrame-Record 0x00 bei OBD-Service $02).\n</li><li>Das <strong>DCM</strong> ruft beim <strong>DEM</strong> die Funktion <code>Dem_GetDTCOfFreezeFrameRecord</code> auf.\n</li><li>Das <strong>DEM</strong> ermittelt aus dem Ereignisspeicher (<code>Event memory</code>) den zugeordneten DTC anhand der gespeicherten Freeze-Frame-Datensätze.\n</li><li>Das <strong>DEM</strong> liefert den DTC als Rückgabewert (<code>Return value(s)</code>) an das <strong>DCM</strong> zurück.\n</li><li>Das <strong>DCM</strong> antwortet dem <strong>External Tester</strong> mit der positiven Antwortnachricht: <code>Response: $42 $02 $00 [ DTC high byte + DTC low byte ]</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht den Ablauf für OBD Service $02 (Mode 02 – Request Powertrain Freeze Frame Data) zur Ermittlung des verursachenden Fehlercodes (DTC) für einen spezifischen Freeze-Frame-Datensatz.\n</li><li>Implementierer müssen sicherstellen, dass das DCM den Freeze-Frame-Datensatzindex korrekt an das DEM über <code>Dem_GetDTCOfFreezeFrameRecord</code> übergibt und die zurückgelieferten High- und Low-Bytes des 2-Byte-OBD-DTCs in das Payload-Format der Service-$02-Antwort einbettet.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c07dbaf7cdeec8fc", "to": "FIG-11676271afaad090", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
